import{_ as i,l as r,o as t,c as p,v as h,p as s,x as l,d as o,i as d,S as c,b as a}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"多 epoch 与重复数据","description":"","frontmatter":{"title":"多 epoch 与重复数据","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/multi-epoch-repetition.md","filePath":"llm/multi-epoch-repetition.md","lastUpdated":1789023840000}'),f={name:"llm/multi-epoch-repetition.md"};function m(E,e,u,R,B,D){const n=r("Mermaid");return t(),p("div",null,[e[1]||(e[1]=h('<h1 id="多-epoch-与重复数据" tabindex="-1">多 epoch 与重复数据 <a class="header-anchor" href="#多-epoch-与重复数据" aria-label="Permalink to &quot;多 epoch 与重复数据&quot;">​</a></h1><div class="epigraph"><p>重复出现的数据先贡献、再伤害：少量重复几乎像新数据，过多重复把曲线从幂律拧成过拟合，解释性上还会长出「背下来」的回路。</p><footer>—— Hernandez et al., Scaling Laws and Interpretability of Learning from Repeated Data, 2022；数据受限设定见 Muennighoff et al., Scaling Data-Constrained Language Models, 2023</footer></div><p><a href="/llm/sequence-length-warmup">上一课</a>假设窗口在变、数据仍是「新 token」。缺口是：唯一字节不够 Chinchilla 配额时，要不要把同一文档看 \\(R\\) 遍。Hernandez 等人测量重复对损失与可解释回路的影响；Muennighoff 等人在数据受限制度下拟合：重复若干 epoch 仍接近新数据，超过某个 \\(R\\) 收益崩掉。本课把「多 epoch」写成缩放轴，而不是默认单遍。后课拟合定律时，重复数据不能当 \\(D\\) 的线性增量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Chinchilla 的 \\(D\\) 常被读成唯一 token。唯一数据 \\(U\\) 小于计算最优 \\(D^*\\) 时，选项是：减小 \\(N\\)、去找更多数据、或重复到 \\(D=R U\\)。Hernandez 的观察：小 \\(R\\) 时重复几乎等价于新数据；\\(R\\) 大时测试损失变差，并且模型对重复序列形成更强的可记忆回路。Muennighoff 等人给出经验：大约 4 epoch 量级内，重复仍有用，再多则饱和——数字随数据与模型变，本课只取「先几乎等价、后饱和伤害」的形状。</p><p>网页抓取里还有<strong>无意重复</strong>：同一页出现在多个分片。无意 \\(R\\) 与有意多 epoch 叠加，真实 \\(R\\) 被低估。去重策略改变有效 \\(U\\)，必须在缩放大本上声明。</p><p><span class="marginnote">验证集若与训练集撞车，多 epoch 会把污染读成「还在降损失」。BPB 课要求固定评测字节；本课要求那些字节与训练唯一文档的重叠率有上限。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记账：</p><ul><li>\\(U\\)：去重后唯一 token（或字节，与词表课一致）。</li><li>\\(R\\)：有意重复遍数；另报无意重复的估计。</li><li>有效数据：\\(D_{\\mathrm{eff}}=U\\cdot f(R)\\)，\\(f(R)\\approx R\\) 当 \\(R\\) 小，\\(f(R)\\) 饱和当 \\(R\\) 大。拟合 \\(L(N,D)\\) 应用 \\(D_{\\mathrm{eff}}\\) 而不是 \\(RU\\)。</li></ul><p>实践：数据受限时优先用满约几个 epoch，而不是把 \\(N\\) 加到按 \\(U\\) 算已经过度的大小（Muennighoff 的主建议方向）。有意重复应打乱顺序，避免同一顺序的 epoch 强化同一梯度方向。高质量子集（书、代码）的 \\(R\\) 可以高于低质量网页，等于配比，不是全局一个 \\(R\\)。</p><p>与稳定性：重复后期梯度变小、\\(v\\) 更低，\\(\\beta_2\\) 尖峰与「背诵」尖峰（同一序列极低损失以外的分布）都更常见。传感器要按 epoch 打事件标记。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>第一次见文档，梯度大，学的是可泛化统计。第 \\(R\\) 次，模型已能低损失预测，梯度指向记忆残差。记忆对训练 CE 有利、对测试 BPB 有害，并在机制上表现为对特定字符串的强注意力回路——Hernandez 把这与可解释性联系起来。因此「训练 CE 还在降」在高 \\(R\\) 下不是继续加 epoch 的理由。</p><p>无意重复相当于把某些文档的 \\(R\\) 提前用满，模型对它们过拟合，对其余欠拟合，平均损失掩盖了不均。去重是缩放实验的数据卫生，不是预处理美感。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理版权与污染治理的法律细节。合成数据若来自同一模型，重复结构更强，\\(f(R)\\) 更差，不能用网页上拟合的 \\(f\\) 去套。下一课写如何拟合 \\(L(N,D)\\)：把 \\(D_{\\mathrm{eff}}\\)、阶段、尖峰剔除都写进回归，否则指数 \\(b\\) 被脏点拉动。</p>',17)),(t(),s(c,null,{default:l(()=>[d(n,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E5%94%AF%E4%B8%80%E6%95%B0%E6%8D%AE%20U%22%5D%20--%3E%20R%5B%22%E9%87%8D%E5%A4%8D%20R%20%E9%81%8D%22%5D%0A%20%20R%20--%3E%20F%5B%22%E6%9C%89%E6%95%88%20D%EF%BC%9A%E5%B0%8F%20R%20%E8%BF%91%E7%BA%BF%E6%80%A7%EF%BC%8C%E5%A4%A7%20R%20%E9%A5%B1%E5%92%8C%22%5D%0A%20%20F%20--%3E%20FIT%5B%22%E8%BF%9B%E5%85%A5%E7%BC%A9%E6%94%BE%E5%BE%8B%E7%9A%84%20D%22%5D%0A%20%20MEM%5B%22%E8%AE%B0%E5%BF%86%E5%9B%9E%E8%B7%AF%22%5D%20--%3E%20R%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[o("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"小 \\(R\\) 的重复接近新数据；大 \\(R\\) 伤害测试并强化记忆回路。"),a("li",null,"缩放用 \\(D_{\\mathrm{eff}}=U f(R)\\)，不要把 \\(RU\\) 当 Chinchilla 的 \\(D\\)。"),a("li",null,"无意重复与有意 epoch 必须一起记账；验证集重叠要有上限。"),a("li",null,"数据受限时先用满有限 epoch，再考虑加 \\(N\\)。"),a("li",null,"出处：Hernandez et al., 2022；Muennighoff et al., 2023。")],-1))])}const g=i(f,[["render",m]]);export{A as __pageData,g as default};
